export function useMorphoMarketHistory(marketId, chainId = UniverseChainId.Mainnet, days = 30) {
  return useQuery({
    queryKey: ["morpho-market-history", marketId, chainId, days],
    queryFn: async () => {
      if (!marketId) return [];
      const startTimestamp = Math.floor(Date.now() / 1e3) - days * 24 * 60 * 60;
      const snapshots = await fetchMarketDailySnapshots(marketId, chainId, startTimestamp);
      return snapshots.map((snapshot) => {
        const supplyAPY = getSupplyRateFromRates(snapshot.rates);
        const borrowAPY = getBorrowRateFromRates(snapshot.rates);
        const totalDepositUSD = parseFloat(snapshot.totalDepositBalanceUSD || "0");
        const totalBorrowUSD = parseFloat(snapshot.totalBorrowBalanceUSD || "0");
        const utilization = totalDepositUSD > 0 ? totalBorrowUSD / totalDepositUSD * 100 : 0;
        return {
          date: new Date(Number(snapshot.timestamp) * 1e3).toLocaleDateString(),
          timestamp: Number(snapshot.timestamp),
          supplyAPY,
          borrowAPY,
          utilization,
          totalValueLockedUSD: parseFloat(snapshot.totalValueLockedUSD || "0"),
          totalDepositUSD,
          totalBorrowUSD
        };
      });
    },
    enabled: !!marketId,
    staleTime: STALE_TIME * 10
  });
}
export function useMorphoProtocolStats(chainId = UniverseChainId.Mainnet) {
  const whitelistedMarketIds = Object.values(MORPHO_MARKETS).filter((m) => m.chainId === chainId).map((m) => m.id.toLowerCase());
  const whitelistedVaultAddresses = Object.values(MORPHO_VAULTS).filter((v) => v.chainId === chainId).map((v) => v.address.toLowerCase());
  return useQuery({
    queryKey: ["morpho-protocol-stats-filtered", chainId, whitelistedMarketIds],
    queryFn: async () => {
      const allMarkets = await fetchMorphoMarkets(chainId, 100);
      if (!allMarkets || allMarkets.length === 0) return null;
      const filteredMarkets = allMarkets.filter((market) => whitelistedMarketIds.includes(market.id.toLowerCase()));
      if (filteredMarkets.length === 0) return null;
      let totalDeposit = 0;
      let totalBorrow = 0;
      let cumulativeDeposit = 0;
      let cumulativeBorrow = 0;
      let cumulativeLiquidate = 0;
      for (const market of filteredMarkets) {
        totalDeposit += parseFloat(market.totalDepositBalanceUSD || "0");
        totalBorrow += parseFloat(market.totalBorrowBalanceUSD || "0");
        cumulativeDeposit += parseFloat(market.cumulativeDepositUSD || "0");
        cumulativeBorrow += parseFloat(market.cumulativeBorrowUSD || "0");
        cumulativeLiquidate += parseFloat(market.cumulativeLiquidateUSD || "0");
      }
      const tvl = totalDeposit - totalBorrow;
      const formatUSD = (value) => {
        if (value >= 1e9) {
          return `$${(value / 1e9).toFixed(2)}B`;
        }
        if (value >= 1e6) {
          return `$${(value / 1e6).toFixed(2)}M`;
        }
        if (value >= 1e3) {
          return `$${(value / 1e3).toFixed(2)}K`;
        }
        return `$${value.toFixed(2)}`;
      };
      return {
        totalValueLockedUSD: tvl,
        totalBorrowUSD: totalBorrow,
        totalDepositUSD: totalDeposit,
        cumulativeDepositUSD: cumulativeDeposit,
        cumulativeBorrowUSD: cumulativeBorrow,
        cumulativeLiquidateUSD: cumulativeLiquidate,
        totalPoolCount: filteredMarkets.length,
        utilization: totalDeposit > 0 ? totalBorrow / totalDeposit * 100 : 0,
        formattedTVL: formatUSD(tvl),
        formattedBorrow: formatUSD(totalBorrow),
        formattedDeposit: formatUSD(totalDeposit)
      };
    },
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
