export function useBorrowMarketAPY(marketId, chainId = UniverseChainId.Mainnet) {
  const { data: market, isLoading } = useMorphoMarketById(marketId, chainId);
  if (!market) {
    return { supplyAPY: null, borrowAPY: null, isLoading };
  }
  return {
    supplyAPY: market.supplyAPY,
    borrowAPY: market.borrowAPY,
    isLoading
  };
}
