"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { X } from "react-feather";
import { Button, Flex, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { formatHealthFactor, getHealthFactorColor } from "../Market/utils/healthFactorUtils";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const ReviewCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const PairHeader = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap8",
  marginBottom: "$spacing24"
});
const Badge = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8"
});
const ArrowPill = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: "$spacing4",
  alignItems: "center",
  justifyContent: "center",
  width: 24,
  height: 24
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center",
  marginLeft: "$spacing8"
});
const Divider = styled(Flex, {
  height: 1,
  backgroundColor: "$surface3",
  width: "100%",
  marginVertical: "$spacing16"
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const InfoRowLabel = styled(Text, {
  color: "$neutral2",
  variant: "body3"
});
const InfoRowValue = styled(Text, {
  color: "$neutral1",
  variant: "body3"
});
const ConfirmButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  height: "56px",
  py: "$spacing24"
});
export default function BorrowReviewModal({
  isOpen,
  onClose,
  onConfirm,
  collateralAmount,
  borrowAmount,
  collateralToken,
  borrowToken,
  transactionType = "borrow",
  currentHealthFactor = Infinity,
  projectedHealthFactor = Infinity,
  currentLtv = 0,
  projectedLtv = 0,
  currentCollateral = 0,
  currentBorrow = 0,
  borrowRate = 0,
  lltvPercent = 0
}) {
  const colors = useSporeColors();
  const isRepay = transactionType === "repay";
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const parsedBorrow = parseFloat(borrowAmount) || 0;
  const hasCollateral = parsedCollateral > 0;
  const hasBorrow = parsedBorrow > 0;
  const getActionLabel = () => {
    if (isRepay) {
      if (hasBorrow && hasCollateral) return "Repay & Withdraw";
      if (hasBorrow) return "Repay Loan";
      if (hasCollateral) return "Withdraw Collateral";
    } else {
      if (hasCollateral && hasBorrow) return "Supply & Borrow";
      if (hasCollateral) return "Supply Collateral";
      if (hasBorrow) return "Borrow";
    }
    return "Review";
  };
  const newCollateral = isRepay ? Math.max(0, currentCollateral - parsedCollateral) : currentCollateral + parsedCollateral;
  const newLoan = isRepay ? Math.max(0, currentBorrow - parsedBorrow) : currentBorrow + parsedBorrow;
  const stats = [
    {
      label: `Collateral (${collateralToken.symbol})`,
      value: <Flex flexDirection="row" alignItems="center" gap="$gap4">
          <InfoRowLabel>{currentCollateral.toFixed(4)} →</InfoRowLabel>
          <InfoRowValue>{newCollateral.toFixed(4)}</InfoRowValue>
        </Flex>
    },
    {
      label: `Loan (${borrowToken.symbol})`,
      value: <Flex flexDirection="row" alignItems="center" gap="$gap4">
          <InfoRowLabel>{currentBorrow.toFixed(4)} →</InfoRowLabel>
          <InfoRowValue>{newLoan.toFixed(4)}</InfoRowValue>
        </Flex>
    },
    {
      label: "Rate",
      value: <InfoRowValue>{borrowRate.toFixed(2)}%</InfoRowValue>
    },
    {
      label: "LTV / Liq. LTV",
      value: <Flex flexDirection="row" alignItems="center" gap="$gap4">
          <InfoRowLabel>{currentLtv.toFixed(2)}% →</InfoRowLabel>
          <InfoRowValue color={projectedLtv > lltvPercent ? "$statusCritical" : "$neutral1"}>
            {projectedLtv.toFixed(2)}%
          </InfoRowValue>
          <InfoRowLabel>/ {lltvPercent.toFixed(1)}%</InfoRowLabel>
        </Flex>
    },
    {
      label: "Health Factor",
      value: <Flex flexDirection="row" alignItems="center" gap="$gap4">
          <Text variant="body3" color={getHealthFactorColor(currentHealthFactor)}>
            {formatHealthFactor(currentHealthFactor)}
          </Text>
          <InfoRowLabel>→</InfoRowLabel>
          <Text variant="body3" color={getHealthFactorColor(projectedHealthFactor)}>
            {formatHealthFactor(projectedHealthFactor)}
          </Text>
        </Flex>
    }
  ];
  return <Modal
    name={"BorrowReviewModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Review
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      <ReviewCard>
        {
    /* Pair Header */
  }
        <PairHeader>
          <Flex flexDirection="row" alignItems="center" mr="$spacing4">
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
    style={{ marginRight: -8, zIndex: 2 }}
  />
            <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
    style={{ zIndex: 1 }}
  />
          </Flex>
          <Text variant="heading3" color="$neutral1">
            {collateralToken.symbol}/{borrowToken.symbol}
          </Text>
          <Badge>
            <Text variant="body4" color="$neutral2">
              {lltvPercent.toFixed(1)}%
            </Text>
          </Badge>
          {
    /* <ArrowPill>
      <ArrowUpRight size={12} color={colors.neutral2?.val ?? '#888'} />
    </ArrowPill> */
  }
        </PairHeader>

        <Text variant="heading3" color="$neutral1" mb="$spacing16">
          {getActionLabel()}
        </Text>

        {isRepay ? <>
            {hasBorrow && <>
                <Text variant="body2" color="$neutral2" mb="$spacing8">
                  Repay Loan
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading3" color="$neutral1">
                      {parsedBorrow}
                    </Text>
                    <Text variant="heading3" color="$neutral2" ml="$spacing4">
                      {borrowToken.symbol}
                    </Text>
                    <UsdPill>
                      <Text variant="body4" color="$neutral2">
                        ${(parsedBorrow * borrowToken.price).toFixed(2)}
                      </Text>
                    </UsdPill>
                  </Flex>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}

            {hasCollateral && <>
                <Text variant="body2" color="$neutral2" mt={hasBorrow ? "$spacing16" : void 0} mb="$spacing8">
                  Withdraw Collateral
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading3" color="$neutral1">
                      {parsedCollateral}
                    </Text>
                    <Text variant="heading3" color="$neutral2" ml="$spacing4">
                      {collateralToken.symbol}
                    </Text>
                    <UsdPill>
                      <Text variant="body4" color="$neutral2">
                        ${(parsedCollateral * collateralToken.price).toFixed(2)}
                      </Text>
                    </UsdPill>
                  </Flex>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}
          </> : <>
            {hasCollateral && <>
                <Text variant="body2" color="$neutral2" mb="$spacing8">
                  Supply Collateral
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading3" color="$neutral1">
                      {parsedCollateral}
                    </Text>
                    <Text variant="heading3" color="$neutral2" ml="$spacing4">
                      {collateralToken.symbol}
                    </Text>
                    <UsdPill>
                      <Text variant="body4" color="$neutral2">
                        ${(parsedCollateral * collateralToken.price).toFixed(2)}
                      </Text>
                    </UsdPill>
                  </Flex>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}

            {hasBorrow && <>
                <Text variant="body2" color="$neutral2" mt={hasCollateral ? "$spacing16" : void 0} mb="$spacing8">
                  Borrow
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading3" color="$neutral1">
                      {parsedBorrow}
                    </Text>
                    <Text variant="heading3" color="$neutral2" ml="$spacing4">
                      {borrowToken.symbol}
                    </Text>
                    <UsdPill>
                      <Text variant="body4" color="$neutral2">
                        ${(parsedBorrow * borrowToken.price).toFixed(2)}
                      </Text>
                    </UsdPill>
                  </Flex>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}
          </>}

        <Divider />

        {
    /* Stats Grid */
  }
        {stats.map((stat, index) => <InfoRow key={stat.label} style={index === stats.length - 1 ? { marginBottom: 0 } : {}}>
            <InfoRowLabel>{stat.label}</InfoRowLabel>
            {stat.value}
          </InfoRow>)}
      </ReviewCard>

      <ConfirmButton onPress={onConfirm}>
        <Button.Text>Confirm</Button.Text>
      </ConfirmButton>
    </Modal>;
}
