function parseTransactionError(error) {
  if (!error) return "Transaction failed";
  const errorMessage = error instanceof Error ? error.message : String(error);
  const lowerMessage = errorMessage.toLowerCase();
  if (lowerMessage.includes("user rejected") || lowerMessage.includes("user denied") || lowerMessage.includes("rejected the request") || lowerMessage.includes("user cancelled") || lowerMessage.includes("user canceled") || lowerMessage.includes("action_rejected")) {
    return "Transaction cancelled";
  }
  if (lowerMessage.includes("insufficient funds") || lowerMessage.includes("insufficient balance")) {
    return "Insufficient funds for gas";
  }
  if (lowerMessage.includes("execution reverted")) {
    if (lowerMessage.includes("insufficient collateral")) return "Insufficient collateral for this borrow amount";
    if (lowerMessage.includes("insufficient liquidity")) return "Insufficient liquidity in market";
    if (lowerMessage.includes("unhealthy position")) return "This would create an unhealthy position";
    return "Transaction would fail - please check your inputs";
  }
  if (lowerMessage.includes("network") || lowerMessage.includes("timeout") || lowerMessage.includes("disconnected")) {
    return "Network error - please try again";
  }
  if (lowerMessage.includes("nonce")) {
    return "Transaction conflict - please try again";
  }
  if (errorMessage.length > 100) {
    return "Transaction failed - please try again";
  }
  return errorMessage;
}
